#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
import json
from pathlib import Path

PAYLOAD = ""

raw = gzip.decompress(base64.b64decode(PAYLOAD)).decode("utf-8")
data = json.loads(raw)
assert data["version"] == "2026.08.4-prototipo"
assert len(data["themes"]) == 10
assert len(data["metrics"]) == 88
Path("data/site-data.json").write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print("Dataset locale v1.2 applicato: 10 temi, 88 indicatori")
